which node && node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
// Search for 'Daniel Ortiz' in the binary and extract surrounding context
const str = data.toString('utf-8');
const idx = str.indexOf('Daniel Ortiz');
if (idx >= 0) {
  // Print surrounding bytes as text for context
  const start = Math.max(0, idx - 200);
  const end = Math.min(str.length, idx + 200);
  const chunk = data.slice(start, end).toString('utf-8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
  console.log(chunk);
}
"

node -e "
const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
const str = data.toString('utf-8');

// Find table schema
const schemaMatch = str.match(/CREATE TABLE[^;]*contacts[^;]*;/i);
if (schemaMatch) console.log('Schema:', schemaMatch[0]);

// Get more context around Daniel Ortiz
const idx = str.indexOf('Daniel Ortiz');
const start = Math.max(0, idx - 50);
const end = Math.min(str.length, idx + 300);
const chunk = data.slice(start, end).toString('utf-8').replace(/[^\x20-\x7E\n\r\t]/g, '|');
console.log('Context:', chunk);
"
